            .on_hover_text(
                "触发期间鼠标位移改用该灵敏度(K2er:覆盖瞄准的灵敏度);0 = 不覆盖。",
            );
        if v.drag_started() || v.gained_focus() {
            undo_needed = true;
        }
    });
