        struct Rig {
            ctl: ControlClient,
            m: Mapper,
            profile: Profile,
            held: Held,
            wheels: Vec<WheelState>,
            fingers: Fingers,
            fps_fingers: Fingers,
            combo_fingers: Fingers,
            macro_down: HashMap<u64, (i32, i32)>,
            macro_exec_seq: u64,
            scheduled: Vec<(Instant, SchedAct)>,
            live: EngineLive,
            gates: PressGates,
            active_android_keys: HashSet<u16>,
